const listDrafts = `-- name: ListDrafts :many
SELECT d.id, d.account_id, d.created_at FROM drafts d
WHERE d.account_id = ?1
  AND (CAST(?2 AS TEXT) IS NULL OR d.id < CAST(?2 AS TEXT))
  AND (CAST(?3 AS INTEGER) IS NULL
    OR CAST(?3 AS INTEGER) = EXISTS (SELECT 1 FROM scheduled_drafts s WHERE s.draft_id = d.id))
ORDER BY d.id DESC
LIMIT ?4
`

type ListDraftsParams struct {
	AccountID string
	BeforeID  sql.NullString
	Scheduled sql.NullInt64
	RowLimit  int64
}

// ListDrafts returns up to @row_limit drafts of @account_id, newest first, before the draft ID
// @before_id (NULL for the first page): every draft, or with @scheduled set the scheduled ones
// (true) or the others (false).
func (q *Queries) ListDrafts(ctx context.Context, arg ListDraftsParams) ([]Draft, error) {
	rows, err := q.db.QueryContext(ctx, listDrafts,
		arg.AccountID,
		arg.BeforeID,
		arg.Scheduled,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Draft{}
	for rows.Next() {
		var i Draft
		if err := rows.Scan(&i.ID, &i.AccountID, &i.CreatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const rebuildScheduledDrafts = `-- name: RebuildScheduledDrafts :exec
INSERT INTO scheduled_drafts (draft_id, schedule_id, account_id, publish_at)
SELECT s.draft_id, s.id, d.account_id, s.publish_at
FROM draft_schedules s JOIN drafts d ON d.id = s.draft_id
WHERE s.id = (
  SELECT max(m.id) FROM draft_schedules m
  WHERE m.draft_id = s.draft_id AND NOT EXISTS (SELECT 1 FROM draft_schedule_outcomes o WHERE o.schedule_id = m.id))
`

func (q *Queries) RebuildScheduledDrafts(ctx context.Context) error {
	_, err := q.db.ExecContext(ctx, rebuildScheduledDrafts)
	return err
}

